var VIEWS=["dashboard","plan","tracker","drives","learn","health","auth"];
function go(v){if(VIEWS.indexOf(v)<0)v="dashboard";document.querySelectorAll(".view").forEach(function(s){s.classList.remove("active")});var el=document.getElementById("view-"+v);if(el)el.classList.add("active");document.querySelectorAll("#topNav button,#bottomNav button").forEach(function(b){b.classList.toggle("active",b.dataset.view===v)});window.scrollTo({top:0,behavior:"smooth"});try{history.replaceState(null,"","#"+v)}catch(e){}if(v==="dashboard")renderDashboard();if(v==="tracker")renderTracker();if(v==="drives")refreshOrganiserUI();}
/* One delegated listener powers EVERY navigation control (nav bars, hero CTAs, in-page buttons) — anything with data-go always routes, no per-button wiring to break. */
document.addEventListener("click",function(e){var t=e.target&&e.target.closest?e.target.closest("[data-go]"):null;if(t){e.preventDefault();go(t.getAttribute("data-go"));}});
window.addEventListener("hashchange",function(){var h=(location.hash||"").replace("#","");if(VIEWS.indexOf(h)>=0)go(h);});
function leafBurst(){return;var em=["🌿","🍃","🌱","✨"];for(var i=0;i<16;i++){var s=document.createElement("span");s.textContent=em[i%4];s.style.cssText="position:fixed;left:50%;top:36%;font-size:"+(16+Math.random()*16)+"px;z-index:200;pointer-events:none";document.body.appendChild(s);var dx=(Math.random()-0.5)*340,dy=130+Math.random()*280,rot=(Math.random()-0.5)*380;(function(el){var a=el.animate([{transform:"translate(0,0) rotate(0deg)",opacity:1},{transform:"translate("+dx+"px,"+dy+"px) rotate("+rot+"deg)",opacity:0}],{duration:1100+Math.random()*500,easing:"cubic-bezier(.2,.7,.3,1)"});if(a)a.onfinish=function(){el.remove()};else setTimeout(function(){el.remove()},1200)})(s)}}
function countUp(el,to,suffix){suffix=suffix||"";var from=parseInt(el.getAttribute("data-v")||"0",10);el.setAttribute("data-v",to);if(from===to||!window.requestAnimationFrame){el.textContent=to+suffix;return}var t0=null;function step(ts){if(!t0)t0=ts;var p=Math.min(1,(ts-t0)/550);el.textContent=Math.round(from+(to-from)*p)+suffix;if(p<1)requestAnimationFrame(step)}requestAnimationFrame(step)}
function toast(msg){var t=document.getElementById("toast");t.textContent=msg;t.classList.add("show");setTimeout(function(){t.classList.remove("show")},2600)}
function esc(s){return String(s).replace(/&/g,"&amp;").replace(/</g,"&lt;")}

/* Monsoon timeline */
(function(){var months=["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];var scores=[38,40,30,28,32,88,96,90,74,58,46,42];var h="";months.forEach(function(m,i){h+='<div class="tl'+(scores[i]>=85?" best":"")+'">'+m+"<small>"+scores[i]+"/100</small></div>"});document.getElementById("monsoonTl").innerHTML=h})();

function survivalPct(){if(!trees.length)return 0;var ok=trees.filter(function(t){return t.health!=="Lost"}).length;return Math.round(ok/trees.length*100)}
function treeQty(t){return t.qty||1;}
function totalTrees(){return trees.reduce(function(s,t){return s+treeQty(t)},0);}
function renderDashboard(){
 var _hd=document.getElementById("heroDrives");if(_hd)_hd.textContent=DRIVES.length+" upcoming drive"+(DRIVES.length===1?"":"s");var _sd=document.getElementById("statDrives");if(_sd)_sd.textContent=DRIVES.length;
 countUp(document.getElementById("statTrees"),totalTrees());
 if(trees.length)countUp(document.getElementById("statSurvival"),Math.round(trees.filter(function(t){return t.health==="Healthy"}).reduce(function(s,t){return s+treeQty(t)},0)/totalTrees()*100),"%");else document.getElementById("statSurvival").textContent="—";
 var need=trees.filter(function(t){return parseInt(t.watered)>=4||t.health!=="Healthy"}).length;
 countUp(document.getElementById("statWater"),need);
 var due=trees.slice().sort(function(a,b){return parseInt(b.watered)-parseInt(a.watered)}).slice(0,3);
 document.getElementById("waterDue").innerHTML=due.length?due.map(function(t){return '<div class="score-row"><span>'+t.species+" — <span class='mini'>"+esc(t.loc)+'</span></span><span class="tag '+(parseInt(t.watered)>=7?"red":"amber")+'">Watered '+t.watered+"</span></div>"}).join(""):'<p class="mini">No trees yet — save a plan to start tracking.</p>';
 document.getElementById("grovePreview").innerHTML=trees.slice(0,3).map(treeCardHTML).join("")||'<div class="card"><p>Your grove is empty. Generate a plan and save it — your trees will appear here.</p></div>';
}
function healthTag(h){return h==="Healthy"?'<span class="tag">● Healthy</span>':h==="Stressed"?'<span class="tag amber">● Stressed</span>':'<span class="tag red">● '+h+"</span>"}
function treeCardHTML(t){var sp=SPECIES.filter(function(s){return s.name===t.species})[0]||{icon:"🌳"};
 return '<div class="card"><div class="tree-card"><div class="avatar">'+sp.icon+'</div><div style="flex:1;min-width:0"><div style="display:flex;justify-content:space-between;gap:8px;flex-wrap:wrap"><b>'+t.species+"</b>"+healthTag(t.health)+'</div><p style="margin-top:4px">📍 '+esc(t.loc)+'<br/>Planted '+t.planted+(treeQty(t)>1?" · ×"+treeQty(t)+" trees":"")+" · 💧 "+t.waters+" waterings · last "+t.watered+'</p></div></div></div>'}

/* Journey selector */
var HINTS={community:"For community drives, maintenance and water matter as much as species.",species:"We'll score your chosen species honestly — a poor fit gets flagged, with a better companion mix suggested, never a silent swap.",date:"Your date is fixed, so the engine focuses on prep work, pit preparation and an irrigation bridge until roots establish.",location:"Your site is fixed, so species and soil treatment adapt to it — not the other way round.",individual:"A few trees, cared for well, beat hundreds planted and forgotten. Small plans get the same rigour."};
document.querySelectorAll(".jcard").forEach(function(c){c.addEventListener("click",function(){document.querySelectorAll(".jcard").forEach(function(x){x.classList.remove("active")});c.classList.add("active");currentJourney=c.dataset.j;document.getElementById("journeyHint").textContent=HINTS[currentJourney];document.getElementById("speciesField").style.display=currentJourney==="species"?"block":"none";if(currentJourney==="individual"){document.getElementById("fCount").value=10}if(currentJourney==="community"&&parseInt(document.getElementById("fCount").value)<50){document.getElementById("fCount").value=250}})});

/* ===== Recommendation engine ===== */
function timingScore(d){var m=d.getMonth()+1,day=d.getDate();
 if(m===7)return 96; if(m===6&&day>=15)return 94; if(m===6)return 86; if(m===8)return 90; if(m===9)return 74; if(m===10)return 58; if(m===11)return 46; if(m===12)return 40; if(m===1)return 42; if(m===2)return 44; if(m===3)return 32; if(m===4)return 27; return 30;}
function matchClass(f){return f>=75?"High":f>=55?"Moderate":"Low";}
function runEngine(){
 var district=document.getElementById("fDistrict").value;
 var dateVal=document.getElementById("fDate").value; if(!dateVal){toast("Please pick a planting date");return}
 var d=new Date(dateVal+"T12:00:00");
 var count=Math.max(1,parseInt(document.getElementById("fCount").value)||1);
 var soil=document.getElementById("fSoil").value;
 var water=document.getElementById("fWater").value;
 var care=document.getElementById("fCare").value;
 var purpose=document.getElementById("fPurpose").value;
 var chosen=currentJourney==="species"?document.getElementById("fSpecies").value:null;
 var D=TALUKAS[district]||PUNE_DISTRICT;
 var tScore=timingScore(d);
 var waterMap={piped:92,borewell:84,pond:68,tanker:76,rain:50}; var wScore=waterMap[water];
 var careMap={caretaker:94,rota:82,club:80,uncertain:45,none:28}; var cScore=careMap[care];
 if(d.getMonth()>=5&&d.getMonth()<=8&&water==="rain")wScore=78; /* monsoon rain-fed is viable */
 var aqiScore=Math.max(40,100-Math.max(0,D.aqi-50));
 /* species fit */
 function fit(sp){var s=60; var soilMatch=sp.soils.indexOf(soil)>=0&&D.ph>=sp.ph[0]&&D.ph<=sp.ph[1]; var rainMatch=D.rain>=sp.rain[0]&&D.rain<=sp.rain[1]; if(soilMatch)s+=26; else s-=14; if(rainMatch)s+=12; else s-=10; if(PUNE_DISTRICT.bonus.indexOf(sp.name)>=0)s+=8; s-=(sp.water-2)*4; if(water==="rain"||water==="tanker")s-=(sp.water-2)*6; if(care==="uncertain"||care==="none")s+=(sp.drought-3)*4; return Math.max(25,Math.min(98,s))}
 var ranked=SPECIES.slice().sort(function(a,b){return fit(b)-fit(a)});
 var mix=[]; var soilScore;
 if(chosen){var cs=SPECIES.filter(function(s){return s.name===chosen})[0]; soilScore=fit(cs); mix.push({sp:cs,pct:45}); ranked=ranked.filter(function(s){return s.name!==chosen}); mix.push({sp:ranked[0],pct:30}); mix.push({sp:ranked[1],pct:25});}
 else{soilScore=Math.round((fit(ranked[0])+fit(ranked[1]))/2); mix=[{sp:ranked[0],pct:40},{sp:ranked[1],pct:35},{sp:ranked[2],pct:25}];}
 var overall=Math.round(tScore*.32+soilScore*.22+wScore*.20+cScore*.16+aqiScore*.10);
 var survival=Math.max(22,Math.min(94,Math.round(overall*.92+ (count<=20?4:0))));
 var monthName=d.toLocaleDateString("en-IN",{day:"numeric",month:"long",year:"numeric"});
 var warnings=[];
 if(tScore<50)warnings.push("⚠️ <strong>"+monthName+" is outside the monsoon window.</strong> Roots will face dry weeks before they establish. Do pit preparation + mulching now, and budget assured irrigation for 90 days — or shift planting to late June–July to lift survival sharply.");
 if(tScore>=85)warnings.push("✅ <strong>Excellent timing.</strong> "+monthName+" sits in the monsoon window — moist soil and rain support will do much of the early watering for you.");
 if(water==="rain"&&tScore<70)warnings.push("⚠️ <strong>Rain-fed only + dry-season date is the riskiest combination.</strong> Add a tanker schedule or drip bottles for the first 90 days.");
 if(care==="none"||care==="uncertain")warnings.push("⚠️ <strong>No confirmed caretaker.</strong> This is the #1 killer in our model. Name one person or a rota before planting day — it moves survival more than species choice.");
 if(chosen){var cf=fit(SPECIES.filter(function(s){return s.name===chosen})[0]); if(cf<60)warnings.push("⚠️ <strong>Your "+chosen+" is a weak fit here ("+cf+"/100)</strong> for "+SOILNAMES[soil]+" soil in "+district+" with this water source. We've kept it as your lead species as requested, but balanced it with stronger companions below. Extra watering will be essential."); else warnings.push("✅ <strong>Your "+chosen+" is a good fit here ("+cf+"/100)</strong> — kept as your lead species, with companions for diversity and pest resilience.");}
 if(soil==="lateritic")warnings.push("🪨 <strong>Lateritic soil:</strong> drains fast — dig 2×2×2 ft pits, backfill with soil + compost, and favour Neem / Karanj / Amla.");
 if(D.aqi>100)warnings.push("🌫️ <strong>"+district+" AQI is "+D.aqi+"</strong> — dense-canopy, high-CO₂ species are prioritised in your mix for maximum air benefit.");
 var litresPerTree=(tScore<60?15:9); var totalWater=(count*litresPerTree).toLocaleString("en-IN");
 var rows=[["🗓️ Timing ("+monthName+")",tScore],["🪨 Soil–species fit ("+SOILNAMES[soil]+")",soilScore],["💧 Water ("+document.getElementById("fWater").selectedOptions[0].text+")",wScore],["🛡️ Maintenance plan",cScore],["🌫️ Air quality — "+district+" taluka (AQI "+D.aqi+")",Math.round(aqiScore)]];
 var color=overall>=80?"var(--green)":overall>=55?"var(--amber)":"var(--red)";
 var verdict=overall>=80?"Strong plan — plant with confidence":overall>=55?"Workable plan — fix the warnings below":"Risky plan — change date, water or care first";
 var _mix=mix.map(function(m){return{species:m.sp.name,n:Math.max(1,Math.round(count*m.pct/100))}}); var _sum=_mix.reduce(function(s,m){return s+m.n},0); _mix[_mix.length-1].n=Math.max(1,_mix[_mix.length-1].n+(count-_sum));
 var mixHTML=mix.map(function(m,i){var n=_mix[i].n;return '<div class="mixrow"><div class="nm">'+m.sp.icon+" "+m.sp.name+'</div><div class="bar" style="flex:1"><i style="width:'+m.pct+'%"></i></div><b>'+m.pct+"%</b><span class='mini'>≈ "+n.toLocaleString("en-IN")+" trees · "+matchClass(fit(m.sp))+" match · fit "+fit(m.sp)+"/100</span></div>"}).join("");
 var html='<div class="card"><div class="dial-wrap"><div style="text-align:center"><div style="font-size:52px;font-weight:900;letter-spacing:-.03em;color:'+color+';line-height:1">'+overall+'<span style="font-size:22px;color:var(--muted)">/100</span></div><div class="stat-lab">Suitability score</div></div><div style="flex:1;min-width:200px"><h3 style="font-size:19px">'+verdict+'</h3><p>'+district+" · "+D.climate+' · '+count.toLocaleString("en-IN")+" trees · for "+purpose.toLowerCase()+'</p><div style="margin-top:8px"><span class="tag">🌱 Expected survival: <b>'+survival+'%</b></span> <span class="tag">💧 First-90-day water: ≈ '+totalWater+' L</span></div></div></div>'
 +rows.map(function(r){return '<div class="score-row"><span>'+r[0]+'</span><span style="display:flex;align-items:center;gap:8px"><span class="bar" style="width:90px"><i style="width:'+r[1]+'%"></i></span><b>'+r[1]+'</b></span></div>'}).join("")
 +'<h3 style="margin-top:16px">Recommended species mix</h3>'+mixHTML
 +warnings.map(function(w,i){return '<div class="'+(w.indexOf("✅")===0?"good":"warn")+'">'+w+"</div>"}).join("")

 +'<h3 style="margin-top:14px">Your first 90 days</h3><p style="text-align:left">1) Dig &amp; compost pits 7 days before planting. 2) Plant early morning; water '+litresPerTree+' L per sapling on day one. 3) Mulch a 1 m ring and fit guards. 4) Water on the schedule above, log it in the Tracker, and do a health check at day 30.</p>'
 +'<button class="btn btn-dark" style="width:100%;margin-top:12px" onclick="savePlanToTracker()">Save this plan to My Trees</button><p class="mini" style="text-align:center;margin-top:8px">Saving creates tracked trees for each species in the mix, shown on your Dashboard and in My Trees.</p></div>';
 document.getElementById("planResult").innerHTML=html;
 lastPlan={district:district,count:count,mix:_mix,date:monthName};
 document.getElementById("planResult").scrollIntoView({behavior:"smooth",block:"start"});
}
function savePlanToTracker(){if(!lastPlan)return; var added=0; lastPlan.mix.forEach(function(m){var k=Math.max(1,m.n||1); added+=k; trees.push({id:nextId++,species:m.species,qty:k,loc:"Pune district — "+lastPlan.district,planted:lastPlan.date,health:"Healthy",watered:"0 days ago",waters:0})}); toast("✅ Plan saved — "+added+" trees added to your tracker"); leafBurst(); renderDashboard(); go("tracker");}

/* ===== Tracker ===== */
function renderTracker(){
 var _total=totalTrees(); var healthy=trees.filter(function(t){return t.health==="Healthy"}).reduce(function(s,t){return s+treeQty(t)},0);
 document.getElementById("trackerStats").innerHTML='<div class="card"><div class="stat-num">'+_total+'</div><div class="stat-lab">Total tracked</div></div><div class="card"><div class="stat-num">'+healthy+'</div><div class="stat-lab">Healthy</div></div><div class="card"><div class="stat-num">'+(_total-healthy)+'</div><div class="stat-lab">Stressed / need care</div></div>';
 document.getElementById("treeList").innerHTML=trees.map(function(t){return treeCardHTML(t)+''}).join("")===""?'<div class="card"><p>No trees yet.</p></div>':trees.map(function(t,i){
  return '<div class="card">'+treeCardHTML(t).replace('<div class="card">','').replace(/<\/div>$/,'')+'<div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:12px"><button class="hbtn" onclick="logWater('+i+')">💧 Log watering</button>'+["Healthy","Stressed","Needs attention"].map(function(h){return '<button class="hbtn'+(t.health===h?" on":"")+'" onclick="setHealth('+i+',\''+h+'\')">'+h+"</button>"}).join("")+"</div></div>"}).join("");
}
function logWater(i){trees[i].waters++; trees[i].watered="0 days ago"; if(trees[i].health==="Stressed")trees[i].health="Healthy"; toast("💧 Watering logged for "+trees[i].species); renderTracker(); renderDashboard();}
function setHealth(i,h){trees[i].health=h; toast("Health updated: "+trees[i].species+" → "+h); renderTracker(); renderDashboard();}
function addTree(){var sp=document.getElementById("aSpecies").value; var loc=document.getElementById("aLoc").value.trim()||"Pune"; var dv=document.getElementById("aDate").value; var ds=dv?new Date(dv+"T12:00:00").toLocaleDateString("en-IN",{day:"numeric",month:"short",year:"numeric"}):"Recently"; trees.push({id:nextId++,species:sp,loc:loc,planted:ds,health:document.getElementById("aHealth").value,watered:"0 days ago",waters:1}); toast("🌳 "+sp+" added to your tracker"); renderTracker(); renderDashboard();}

/* ===== Drives ===== */
function renderDrives(filter){filter=filter||"all";var _ds=document.getElementById("drivesSub");if(_ds)_ds.textContent=DRIVES.length+" upcoming drive"+(DRIVES.length===1?"":"s")+" across Pune district. Select a drive and complete a short registration form to confirm your place.";
 document.getElementById("driveGrid").innerHTML=DRIVES.filter(function(d){return filter==="all"||d.type===filter||d.city===filter}).map(function(d){var joined=joinedDrives[d.id];
 return '<div class="card drive-card"><div class="drive-img"><img src="'+d.img+'" alt="Plantation drive at '+esc(d.venue)+'"/></div><div style="display:flex;gap:6px;flex-wrap:wrap"><span class="tag">'+d.type+'</span><span class="tag">'+d.city+'</span>'+(joined?'<span class="tag" style="background:var(--deep2);color:#fff">✓ You\'re in · '+joined+' volunteer(s)</span>':"")+'</div><h3 style="margin-top:10px">'+d.title+'</h3><p>🏢 '+d.org+'<br/>🗓️ '+d.date+" · "+d.time+'<br/>📍 '+d.venue+'<br/>🌱 '+d.trees+' trees planned · 👥 '+(d.joinedDb?d.joined:d.joined+(joined||0))+' joined</p><button class="btn '+(joined?"btn-ghost":"btn-primary")+'" style="width:100%;margin-top:12px" onclick="openJoin('+d.id+')">'+(joined?"Update my registration":"Join this drive")+"</button></div>"}).join("")||'<div class="card"><p>No drives match this filter yet.</p></div>';}
document.querySelectorAll("#driveChips .chip").forEach(function(c){c.addEventListener("click",function(){document.querySelectorAll("#driveChips .chip").forEach(function(x){x.classList.remove("active")});c.classList.add("active");renderDrives(c.dataset.f)})});
function openJoin(id){joinTarget=DRIVES.filter(function(d){return d.id===id})[0]; document.getElementById("joinTitle").textContent=joinTarget.title; document.getElementById("joinSub").textContent=joinTarget.date+" · "+joinTarget.time+" · "+joinTarget.venue; document.getElementById("joinForm").style.display="block"; document.getElementById("joinDone").style.display="none"; document.getElementById("joinModal").classList.add("open");}
function closeJoin(){document.getElementById("joinModal").classList.remove("open")}
function submitJoin(){var name=document.getElementById("jName").value.trim(); var phone=document.getElementById("jPhone").value.trim(); if(name.length<2){toast("Please add your name");return} if(phone.replace(/\D/g,"").length<10){toast("Please add a valid 10-digit mobile number");return} var n=Math.max(1,parseInt(document.getElementById("jCount").value)||1); joinedDrives[joinTarget.id]=n; leafBurst(); document.getElementById("joinForm").style.display="none"; document.getElementById("joinDone").style.display="block"; document.getElementById("joinDoneText").innerHTML="Thanks, <b>"+esc(name)+"</b> — <b>"+n+" volunteer(s)</b> registered for <b>"+joinTarget.title+"</b> on "+joinTarget.date+" at "+joinTarget.time+".<br/>Reporting point: "+joinTarget.venue+". The organiser will call "+esc(phone)+" a day before to confirm."; renderDrives(document.querySelector("#driveChips .chip.active").dataset.f);}

/* ===== Learn / species ===== */
function renderSpecies(){var q=(document.getElementById("spSearch").value||"").toLowerCase();
 document.getElementById("speciesGrid").innerHTML=SPECIES.filter(function(s){return (s.name+" "+s.use+" "+s.soils.join(" ")).toLowerCase().indexOf(q)>=0}).map(function(s){return '<div class="card"><div style="font-size:30px">'+s.icon+'</div><h3>'+s.name+'</h3><p>'+s.note+'</p><div style="margin-top:10px;display:grid;gap:5px" class="mini"><span>💧 Water need: '+'●'.repeat(s.water)+'○'.repeat(5-s.water)+' &nbsp;🛡️ Drought tolerance: '+s.drought+'/5</span><span>📏 Mature height: '+s.height+' · Growth: '+s.growth+'</span><span>🪨 Best soil: '+s.soils.map(function(x){return SOILNAMES[x]}).join(", ")+'</span><span>🎯 Best for: '+s.use+' · CO₂: '+s.co2+'</span><span>📏 Spacing: '+s.spacing+' m · Soil pH '+s.ph[0]+'–'+s.ph[1]+' · Rain '+s.rain[0]+'–'+s.rain[1]+' mm</span><span>🔬 '+s.sci+'</span></div></div>'}).join("")||'<div class="card"><p>No species match that search.</p></div>';}

/* ===== Health check ===== */
function runScan(label,seed){document.getElementById("scanLabel").textContent=label; var bar=document.getElementById("scanBar"); var steps=["Reading leaf colour & canopy density…","Checking for stress patterns…","Comparing against healthy reference…","Preparing care advice…"]; var i=0; bar.style.width="8%";
 var iv=setInterval(function(){i++; bar.style.width=Math.min(100,8+i*24)+"%"; if(i<=steps.length)document.getElementById("scanLabel").textContent=steps[Math.min(i,steps.length-1)]; if(i>=4){clearInterval(iv); document.getElementById("scanLabel").textContent="Check complete"; showHealth(seed)}},650);}
function showHealth(seed){var h=62+(seed%30); var stressed=h<75;
 document.getElementById("healthResult").innerHTML='<div class="card"><div style="display:flex;justify-content:space-between;flex-wrap:wrap;gap:8px"><h3>Health report</h3><span class="tag '+(stressed?"amber":"")+'">'+(stressed?"● Needs care":"● Looking healthy")+'</span></div><div style="font-size:44px;font-weight:900;letter-spacing:-.02em">'+h+'<span style="font-size:20px;color:var(--muted)">/100 health index</span></div>'
 +'<div class="score-row"><span>🍃 Leaf vibrancy</span><b>'+(h-4)+'/100</b></div><div class="score-row"><span>🌿 Canopy density</span><b>'+(h+3)+'/100</b></div><div class="score-row"><span>⚠️ Stress signs</span><b>'+(stressed?"Mild yellowing at edges":"None obvious")+'</b></div>'
 +(stressed?'<div class="warn">💧 <strong>Likely cause: water stress.</strong> Edge yellowing with otherwise healthy new growth usually means irregular watering rather than disease.</div>':'<div class="good">✅ No disease-pattern or severe stress signs in this check. Keep the current routine.</div>')
 +'<p style="text-align:left;margin-top:10px"><strong>Next actions:</strong> '+(stressed?'Deep-water 10–15 L early tomorrow morning, add a mulch ring, and re-check in 7 days. If yellowing spreads to new leaves, send a closer leaf photo to your drive organiser.':'Water as scheduled, refresh mulch this month, and re-check in 30 days or after any heatwave.')+'</p><p class="mini">Guidance is indicative — for spreading yellowing, wilting or pests, get a field check.</p></div>';}
function onHealthPhoto(ev){var f=ev.target.files[0]; if(!f)return; var r=new FileReader(); r.onload=function(){document.getElementById("healthPreview").innerHTML='<img src="'+r.result+'" alt="Your uploaded tree photo" style="width:100%;max-height:260px;object-fit:cover;border-radius:14px"/>'; runScan("Analysing your photo…",(f.size+f.name.length*37)%97)}; r.readAsDataURL(f);}
function demoHealthPhoto(){document.getElementById("healthPreview").innerHTML='<img src="data:image/jpeg;base64," alt="Sample photo: hands watering a young sapling, close-up of healthy green leaves" style="width:100%;max-height:260px;object-fit:cover;border-radius:14px"/>'; runScan("Analysing sample tree…",41);}

renderDashboard(); renderDrives("all"); renderSpecies(); renderTracker();

/* ===== Account / login (UI only — the auth calls live in supabase.js) ===== */
var _authRole="individual";
function showAuthTab(which){document.getElementById("authSignIn").style.display=which==="in"?"block":"none";document.getElementById("authSignUp").style.display=which==="up"?"block":"none";document.getElementById("tabSignIn").classList.toggle("active",which==="in");document.getElementById("tabSignUp").classList.toggle("active",which==="up");}
function pickRole(r){_authRole=r;document.querySelectorAll("#roleChips .chip").forEach(function(c){c.classList.toggle("active",c.dataset.role===r)});document.getElementById("orgField").style.display=r==="individual"?"none":"block";}
function toggleDriveForm(){var f=document.getElementById("driveForm");f.style.display=f.style.display==="none"?"block":"none";}
function doSignIn(){if(window.GWAuth)window.GWAuth.signIn();}
function doSignUp(){if(window.GWAuth)window.GWAuth.signUp(_authRole);}
function doSignOut(){if(window.GWAuth)window.GWAuth.signOut();}
function doResetPassword(){if(window.GWAuth)window.GWAuth.resetPassword();}
function continueAsGuest(){go("dashboard");toast("Browsing as a guest — your trees save on this device.");}
function submitDrive(){if(window.GWAuth)window.GWAuth.createDrive();}
function authErr(which,msg){var el=document.getElementById(which==="in"?"authErrIn":"authErrUp");if(!el)return;if(!msg){el.style.display="none";return;}el.textContent=msg;el.style.display="block";}
function isOrganiser(){var r=(window.GWProfile&&window.GWProfile.role)||"";return ["ngo","college","municipal","csr"].indexOf(r)>=0;}
function refreshOrganiserUI(){var org=isOrganiser();var ob=document.getElementById("organiseBox");if(ob)ob.style.display=org?"block":"none";var mb=document.getElementById("myDrivesBox");if(mb)mb.style.display=org?"block":"none";if(org&&window.GWAuth&&window.GWAuth.loadMyDrives)window.GWAuth.loadMyDrives();}

var _h=(location.hash||"").replace("#",""); if(VIEWS.indexOf(_h)>=0&&_h!=="dashboard")go(_h);
